-- 전주 합죽선(p31) 상품 상세 소개를 AI 상세 페이지 결과로 심는다. 원본: scripts/demo-products/seed_detail_content.py
-- content_block 은 소비자 상세가 순서대로 보여 주고, react_document 는 판매자 미리보기·편집에서 같은 내용을 연다.

CREATE TEMP TABLE demo_detail_blocks (display_order SMALLINT, tag VARCHAR(10), body VARCHAR(2000), image_url VARCHAR(500)) ON COMMIT DROP;
INSERT INTO demo_detail_blocks VALUES
    (1, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/01-hero.webp'),
    (2, 'h2', '매화 한 획씩 직접 그린 부채', NULL),
    (3, 'p', '담양 왕대를 3년 건조해 손으로 깎은 대나무 뼈대와 한지 선면 위에 매화를 그렸습니다. 같은 부채가 하나도 없는, 한 획의 차이가 살아 있는 전주 합죽선입니다.', NULL),
    (4, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/02-packshot.webp'),
    (5, 'h2', '3년 건조한 대나무, 손으로 깎은 선면', NULL),
    (6, 'p', '담양 왕대를 3년 동안 건조한 뒤 손으로 겉대와 속대를 깎아 부채의 뼈대를 만듭니다. 그 위에 한지를 겹겹이 붙여 선면을 만들고, 매화를 한 획씩 직접 그려 완성합니다.', NULL),
    (7, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/03-detail.webp'),
    (8, 'h2', '한지 선면 위의 매화', NULL),
    (9, 'p', '흰 한지 선면 위에 검은 먹과 분홍빛 매화가 대나무 뼈대 사이로 이어집니다. 선면의 결과 문양의 흐름이 한 장의 그림처럼 읽힙니다.', NULL),
    (10, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/06-detail-02.webp'),
    (11, 'h2', '흰 한지와 먹, 분홍 매화', NULL),
    (12, 'p', '부채의 색은 흰 한지, 검은 먹, 분홍 매화 세 가지로 정리됩니다. 대나무의 자연스러운 색이 이 세 가지 색을 받쳐줍니다.
· 흰 한지 — 선면의 기본 배경. 부채 전체를 밝고 차분하게 받치는 색
· 검은 먹 — 매화 가지와 줄기. 선면 위를 흐르는 검은 곡선
· 분홍 매화 — 꽃과 꽃봉오리. 검은 가지 사이로 피어나는 색', NULL),
    (13, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/04-lifestyle.webp'),
    (14, 'h2', '손에 들면 그림이 되는 부채', NULL),
    (15, 'p', '부채를 펼치면 선면의 매화가 손안에서 그림이 됩니다. 부채로 바람을 부는 순간에도 선면의 문양이 함께 움직입니다.', NULL),
    (16, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/05-lifestyle-02.webp'),
    (17, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/07-detail-03.webp'),
    (18, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/08-detail-04.webp'),
    (19, 'img', NULL, 'https://raw.githubusercontent.com/Jangingmall/backend/develop/docs/demo-products/detail/p31/09-detail-05.webp'),
    (20, 'h2', '부채의 각도', NULL),
    (21, 'p', '부채의 전체 형태와 선면의 매화 문양, 대나무 뼈대의 결을 각도별로 살펴봅니다.', NULL),
    (22, 'h2', '전주 부채 시리즈', NULL),
    (23, 'p', '같은 제작 방식과 한지 선면으로 완성된 다른 문양의 부채를 함께 살펴보세요.', NULL),
    (24, 'h2', '부채를 오래 쓰는 방법', NULL),
    (25, 'p', '펼칠 때는 아래에서 위로 천천히 펴 주세요. 사용 후에는 접어 직사광선과 습기를 피해 보관하면 오래 쓸 수 있습니다. 물티슈·물세척은 한지가 상하니 피해 주세요.
· 펼칠 때 — 아래에서 위로 천천히 펴기. 부채의 뼈대와 선면을 보호하는 방법
· 보관 — 접어 직사광선·습기 피하기. 한지 선면이 변색되거나 상하는 것을 막는 방법
· 세척 금지 — 물티슈·물세척 금지. 한지가 물에 상할 수 있으므로 물로 닦지 않기', NULL),
    (26, 'h2', '한 획의 차이가 만드는 부채', NULL),
    (27, 'p', '매화를 한 획씩 직접 그리기 때문에 같은 부채가 하나도 없습니다. 전주 합죽선 매화선은 손의 흔적이 선면에 남은 부채입니다.', NULL);

